intro:
Creates an std::exception_ptr that holds a reference to a copy of e. This is done as if executing the following code:

try
{
    throw e;
}
catch(...)
{
    return std::current_exception();
}

examples.code:
#include <exception>
#include <stdexcept>
#include <system_error>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>
#include <cstdlib>
void handler() { std::_Exit(1); }
int main() {
    std::exception base, copy;
    copy = base;
    assert(base.what());
    std::bad_exception bad, other;
    other = bad;
    assert(bad.what());
    std::system_error failure{
        std::make_error_code(std::errc::invalid_argument), "input"};
    assert(failure.code() == std::errc::invalid_argument);
    assert(*failure.what());
    const auto &category = std::generic_category();
    assert(*category.name());
    assert(!category.message(1).empty());
    assert(category == category);
    assert(category.default_error_condition(1).value() == 1);
    auto code = std::make_error_code(std::errc::invalid_argument);
    assert(category.equivalent(code.value(), code.default_error_condition()));
    assert(category.equivalent(code, code.value()));
    static_assert(std::is_error_condition_enum<std::errc>::value);
    auto terminate = std::get_terminate();
    assert(terminate);
    std::terminate_handler previous = std::set_terminate(handler);
    assert(std::get_terminate() == handler);
    std::set_terminate(previous);
    try {
        throw std::runtime_error("inner");
    } catch (...) {
        auto pointer = std::make_exception_ptr(std::runtime_error("message"));
        try {
            std::rethrow_exception(pointer);
        } catch (const std::runtime_error &e) {
            assert(std::string(e.what()) == "message");
        }
    }
    try {
        try {
            throw std::runtime_error("inner");
        } catch (...) {
            std::throw_with_nested(std::logic_error("outer"));
        }
    } catch (const std::exception &e) {
        auto nested = dynamic_cast<const std::nested_exception *>(&e);
        assert(nested && nested->nested_ptr());
        std::nested_exception clone{*nested};
        clone = *nested;
        try {
            clone.rethrow_nested();
        } catch (const std::runtime_error &inner) {
            assert(std::string(inner.what()) == "inner");
        }
    }
}
